#[test]
fn 選んでいないdcmpファイルの監視の停止を拒むと張ってある監視は続く() {
    let dir = TempDir::new("watch-edge");
    let record_dir = TempDir::new("watch-edge-record");
    let path = chosen_file_path(&dir, "document.dcmp");
    fs::write(&path, r#"{"version":1}"#).expect("監視対象を用意できる");
    let chosen = chosen_paths_in(&record_dir);
    let known = Arc::new(KnownContentRegistry::new());
    let watchers = DocumentWatchers::new();
    let changes = watch_changes(&watchers, &known, &path);

    let _ = watch::stop_requested(
        WatchManagedState::new(&chosen, &known, &watchers),
        &path.spelling(),
    );
    fs::write(&path, r#"{"version":2}"#).expect("外部からの書き込みができる");

    assert_eq!(next_change(&changes), r#"{"version":2}"#);
}

test("選ばれたものを Rust が受け付けなかったときは、その理由の原文が失敗に残る", async () => {
  const fake = createDocumentDialogFake({
    open: DialogChoice.refused("/work/notes.txt: 拡張子が `.dcmp` ではない"),
    save: DialogChoice.Canceled,
  });

  const chosen = await fake.dialog.chooseOpenPath();

  expect(chosen).toStrictEqual(
    Result.err({ message: "/work/notes.txt: 拡張子が `.dcmp` ではない" }),
  );
});

test("ダイアログのコマンドが文字列でも null でもない値を返すと、その旨と受け取った値が失敗に残る", async () => {
  // 本物の Rust は返さない値なので、代役ではなく値を返すだけの IPC を組む。
  const tauriIpc: TauriIpc = {
    invoke() {
      return Promise.resolve(42);
    },
    listen(event) {
      return ipcFailure(`Event ${event} not emitted`);
    },
  };
  const dialog = createDocumentDialog(tauriIpc);

  const chosen = await dialog.chooseOpenPath();

  expect(chosen).toStrictEqual(
    Result.err({
      message: "choose_open_document_path が文字列以外を返した: 42",
    }),
  );
});

test("Rust が document-dropped で知らせたドロップが届く", async () => {
  // 代役の定数を通さず綴りで書く。Rust 側の `DOCUMENT_DROPPED_EVENT` と片側だけ変えると落ちる。
  const rustEvents = createSingleEventIpcFake("document-dropped");
  const drop = createFileDrop(rustEvents.ipc);
  const received: (readonly string[])[] = [];
  Result.unwrap(
    await drop.subscribeDropped((paths) => {
      received.push(paths);
    }),
  );

  rustEvents.deliver({ paths: [Path] });

  expect(received).toStrictEqual([[Path]]);
});

test("Tauri 自身が配るドロップの通知では配られない", async () => {
  // 開いてよいものとして記録される前に届く通知なので、聞いていれば落ちる。
  const tauriDragDrop = createSingleEventIpcFake("tauri://drag-drop");
  const drop = createFileDrop(tauriDragDrop.ipc);
  const received: (readonly string[])[] = [];
  await drop.subscribeDropped((paths) => {
    received.push(paths);
  });

  tauriDragDrop.deliver({ paths: [Path], position: { x: 0, y: 0 } });

  expect(received).toStrictEqual([]);
});

